<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Request · Lex Factum Admin</title><link rel="stylesheet" href="<?= base_url('styles.css') ?>"><style>body{background:#080a0c;color:#eee;font-family:Arial,sans-serif}.wrap{max-width:900px;margin:auto;padding:35px}.back{color:#d8b979;text-decoration:none;font-size:12px}.card{margin-top:25px;padding:28px;border:1px solid rgba(255,255,255,.09);border-radius:18px;background:rgba(255,255,255,.03)}.ey{color:#c8a66e;letter-spacing:.16em;font-size:10px}.h{font:500 42px Georgia,serif;margin:10px 0 25px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.label{color:#777f82;font-size:10px;letter-spacing:.12em}.value{margin-top:6px;color:#ddd}.message{margin-top:25px;padding:20px;border-radius:12px;background:rgba(255,255,255,.035);line-height:1.7;white-space:pre-wrap}.status{margin-top:25px;display:flex;gap:10px;align-items:center}.status select,.status button{padding:10px 12px;background:#15181b;color:#ddd;border:1px solid #333;border-radius:8px}.status button{color:#e0bd7c}.danger{color:#c97b7b;text-decoration:none;margin-left:15px}</style></head><body><main class="wrap"><a class="back" href="<?= site_url('admin/enquiries') ?>">← All requests</a><div class="card"><div class="ey"><?= esc(strtoupper($item['type'] ?? 'contact')) ?></div><h1 class="h"><?= esc($item['full_name']) ?></h1><div class="grid"><div><div class="label">EMAIL</div><div class="value"><?= esc($item['email']) ?></div></div><div><div class="label">PHONE</div><div class="value"><?= esc($item['phone'] ?? '') ?></div></div><div><div class="label">PRACTICE AREA</div><div class="value"><?= esc($item['practice_area'] ?? '') ?></div></div><div><div class="label">PREFERRED DATE / TIME</div><div class="value"><?= esc($item['preferred_date'] ?? '') ?> <?= esc($item['preferred_time'] ?? '') ?></div></div></div><div class="message"><?= esc($item['message'] ?? '') ?></div><form class="status" method="post" action="<?= site_url('admin/enquiries/'.$item['id'].'/status') ?>"><?= csrf_field() ?><span class="label">STATUS</span><select name="status"><option value="new" <?= $item['status']==='new'?'selected':'' ?>>New</option><option value="contacted" <?= $item['status']==='contacted'?'selected':'' ?>>Contacted</option><option value="scheduled" <?= $item['status']==='scheduled'?'selected':'' ?>>Scheduled</option><option value="closed" <?= $item['status']==='closed'?'selected':'' ?>>Closed</option><option value="spam" <?= $item['status']==='spam'?'selected':'' ?>>Spam</option></select><button>Save status</button><a class="danger" href="<?= site_url('admin/enquiries/'.$item['id'].'/delete') ?>" onclick="return confirm('Delete this request?')">Delete</a></form></div></main></body></html>
